#include <cuda_runtime.h>
#include <vector>
#include <algorithm>
#include <functional>
#define main legacy_main
#include "../blas-gemm-cuda/main.cu"
#undef main
#define CK(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(1);}}while(0)
#define BK(x) do{auto e=(x);if(e!=CUBLAS_STATUS_SUCCESS){fprintf(stderr,"cublasstatus%d\n",int(e));exit(1);}}while(0)
struct Case{std::function<void()>launch,reset,collect;double t;};
template<class T>Case make_case(cublasHandle_t handle,int repeat,std::vector<double>*output,bool*ok){int m=64,k=32,n=48;srand(2);std::vector<T>a(m*k),b(k*n),c(m*n);for(auto&v:a)v=T(rand()%2);for(auto&v:b)v=T(rand()%2);for(auto&v:c)v=T(rand()%2);std::vector<double>expected(m*n);for(int row=0;row<m;row++)for(int col=0;col<n;col++){double s=0;for(int q=0;q<k;q++)s+=double(a[row*k+q])*double(b[q*n+col]);expected[row*n+col]=2*s+.5*double(c[row*n+col]);}T *da,*db,*dc;CK(cudaMalloc(&da,a.size()*sizeof(T)));CK(cudaMalloc(&db,b.size()*sizeof(T)));CK(cudaMalloc(&dc,c.size()*sizeof(T)));CK(cudaMemcpy(da,a.data(),a.size()*sizeof(T),cudaMemcpyHostToDevice));CK(cudaMemcpy(db,b.data(),b.size()*sizeof(T),cudaMemcpyHostToDevice));auto launch=[=](){T alpha=T(2),beta=T(.5);if constexpr(std::is_same_v<T,half>){BK(cublasHgemm(handle,CUBLAS_OP_N,CUBLAS_OP_N,n,m,k,&alpha,db,n,da,k,&beta,dc,n));}else if constexpr(std::is_same_v<T,float>){BK(cublasSgemm(handle,CUBLAS_OP_N,CUBLAS_OP_N,n,m,k,&alpha,db,n,da,k,&beta,dc,n));}else {BK(cublasDgemm(handle,CUBLAS_OP_N,CUBLAS_OP_N,n,m,k,&alpha,db,n,da,k,&beta,dc,n));}};auto reset=[=](){CK(cudaMemcpy(dc,c.data(),c.size()*sizeof(T),cudaMemcpyHostToDevice));CK(cudaDeviceSynchronize());};auto collect=[=](){std::vector<T>got(c.size());CK(cudaMemcpy(got.data(),dc,c.size()*sizeof(T),cudaMemcpyDeviceToHost));for(int i=0;i<got.size();i++){double v=double(got[i]);*ok&=std::isfinite(v)&&v==expected[i];output->push_back(v);}};reset();launch();CK(cudaDeviceSynchronize());return {launch,reset,collect,0};}
int main(int argc,char**argv){int repeat=argc>1?atoi(argv[1]):10;cublasHandle_t h;BK(cublasCreate(&h));int version;BK(cublasGetVersion(h,&version));printf("STUDY_LIBRARY native_CUBLAS %d\n",version);std::vector<double>output;bool ok=true;auto a=make_case<half>(h,repeat,&output,&ok),b=make_case<float>(h,repeat,&output,&ok),c=make_case<double>(h,repeat,&output,&ok);std::vector<Case>cases{a,b,c};bool all=true;for(int trial=1;trial<=5;trial++){output.clear();ok=true;for(auto&x:cases){x.t=0;for(int rep=0;rep<repeat;rep++){x.reset();auto t0=std::chrono::steady_clock::now();x.launch();CK(cudaDeviceSynchronize());x.t+=std::chrono::duration<double>(std::chrono::steady_clock::now()-t0).count()/repeat;}x.collect();}all&=ok;char file[100];sprintf(file,"blas_gemm_trial%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(output.data(),8,output.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%d,\"max_abs_error\":0,\"max_rel_error\":0,\"timing_region\":\"sum_FP16_FP32_FP64_GEMM_alpha2_betaHalf_one_operation_reset_excluded\",\"jit_excluded\":true,\"internal_repeats\":%d,\"dtype_times_seconds\":[%.12g,%.12g,%.12g],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%d,\"byte_order\":\"little\"}}\n",trial,cases[0].t+cases[1].t+cases[2].t,ok?"true":"false",int(output.size()),repeat,cases[0].t,cases[1].t,cases[2].t,file,int(output.size()));}BK(cublasDestroy(h));puts(all?"PASS":"FAIL");return all?0:1;}
